def patch_settings(current, patch):
    result = dict(current)
    for key, value in patch.items():
        result[key] = value or current.get(key)
    return result
from settings import patch_settings


def update_preferences(current, payload):
    patch = {key: payload[key] for key in ("note", "enabled") if key in payload}
    return patch_settings(current, patch)
from settings import patch_settings


def clear_note(current):
    return patch_settings(current, {"note": None})
import unittest
from api import update_preferences


class SettingsTests(unittest.TestCase):
    def test_updates_note(self):
        original = {"note": "before", "enabled": True}
        result = update_preferences(original, {"note": "after"})
        self.assertEqual(result, {"note": "after", "enabled": True})
        self.assertEqual(original["note"], "before")
